compute.getter:

import io.nop.core.dict.DictProvider;
import io.nop.api.core.beans.DictBean;

// 填充enableStatus字段的字典翻译
if (entity.enableStatus != null) {
    let dict = DictProvider.instance().getDict(null, "dahua/enableStatus", null, null);
    if (dict != null) {
        let option = dict.getOptionByValue(entity.enableStatus);
        if (option != null) {
            return option.label;
        }
    }
}
